const input = $input.first().json;
const trigger = $('Research Trigger').first().json;
const topic = trigger.body?.topic || trigger.topic || 'Research';

let content = `## ${topic}\n\n`;
if (input.answer) {
  content += `### AI Summary\n${input.answer}\n\n`;
}
content += `### Sources\n`;
if (input.results) {
  for (const r of input.results.slice(0, 5)) {
    content += `- **${r.title}**\n  ${r.url}\n  ${(r.content || '').substring(0, 300)}...\n\n`;
  }
}

return [{ json: { title: `Research: ${topic}`, content, answer: input.answer || '', sources: input.results?.length || 0 } }];
